public class CommandLineRunner_createOptions_TriageGen0Test {

    private TestableCommandLineRunner runner;
    private CommandLineRunner.Flags flags;

    // Subclass to expose the protected method for testing
    private static class TestableCommandLineRunner extends CommandLineRunner {
        public TestableCommandLineRunner(String[] args) {
            super(args);
        }

        @Override
        public CompilerOptions createOptions() {
            return super.createOptions();
        }
    }

    @Before
    public void setUp() throws Exception {
        runner = new TestableCommandLineRunner(new String[]{});
        flags = new CommandLineRunner.Flags();

        // Use reflection to inject the flags object into the runner if it's a field
        Field flagsField = CommandLineRunner.class.getDeclaredField("flags");
        flagsField.setAccessible(true);
        flagsField.set(runner, flags);

        // Initialize mandatory flag objects to avoid NullPointerException
        flags.compilation_level = mock(CompilationLevel.class);
        flags.warning_level = mock(WarningLevel.class);
        flags.formatting = Collections.emptyList();
        flags.debug = false;
        flags.generate_exports = false;
        flags.process_closure_primitives = false;
    }

    @Test
    public void testCreateOptions_DefaultValues() {
        CompilerOptions options = runner.createOptions();

        assertThat(options).isNotNull();
        verify(flags.compilation_level).setOptionsForCompilationLevel(options);
        verify(flags.warning_level).setOptionsForWarningLevel(options);
        assertThat(options.closurePass).isFalse();
        assertThat(options.getGenerateExports()).isFalse();
    }

    @Test
    public void testCreateOptions_WithDebugTrue() {
        flags.debug = true;

        CompilerOptions options = runner.createOptions();

        verify(flags.compilation_level).setDebugOptionsForCompilationLevel(options);
    }

    @Test
    public void testCreateOptions_WithGenerateExportsTrue() {
        flags.generate_exports = true;

        CompilerOptions options = runner.createOptions();

        assertThat(options.getGenerateExports()).isTrue();
    }

    @Test
    public void testCreateOptions_WithFormattingOptions() {
        FormattingOption mockFormat = mock(FormattingOption.class);
        flags.formatting = Collections.singletonList(mockFormat);

        CompilerOptions options = runner.createOptions();

        verify(mockFormat).applyToOptions(options);
    }

    @Test
    public void testCreateOptions_WithClosurePrimitivesTrue() {
        flags.process_closure_primitives = true;

        CompilerOptions options = runner.createOptions();

        assertThat(options.closurePass).isTrue();
    }

    @Test
    public void testCreateOptions_FullCoverage() {
        // Combining all branches to ensure maximum coverage in one complex path
        flags.debug = true;
        flags.generate_exports = true;
        flags.process_closure_primitives = true;

        FormattingOption mockFormat = mock(FormattingOption.class);
        flags.formatting = Collections.singletonList(mockFormat);

        CompilerOptions options = runner.createOptions();

        assertThat(options.getGenerateExports()).isTrue();
        assertThat(options.closurePass).isTrue();
        verify(flags.compilation_level).setDebugOptionsForCompilationLevel(options);
        verify(mockFormat).applyToOptions(options);
    }
}
